    "Another device already resolved these settings. The server version is now saved on this phone.": "दूसरे डिवाइस पर ये सेटिंग पहले ही सुलझा दी गई हैं। सर्वर वाली सेटिंग इस फ़ोन पर सहेज दी गई है।",
