    "Purchase Amount: {{purchase}}\nAdjusted From Advance: {{adjusted}}\nNew Outstanding: {{outstanding}}": "खरीद की राशि: {{purchase}}\nअग्रिम से समायोजित: {{adjusted}}\nनया बकाया: {{outstanding}}",
