    "Check the API connection and try again. Your last server data remains unchanged.": "API कनेक्शन जाँचकर फिर कोशिश करें। सर्वर का पिछला डेटा नहीं बदला है।",
    "Check your connection and open Notifications again to retry.": "कनेक्शन जाँचें और फिर कोशिश करने के लिए सूचनाएँ दोबारा खोलें।",
    "Checkout is disabled until Android billing eligibility and a supported native payment integration are confirmed.": "Android बिलिंग पात्रता और समर्थित भुगतान सुविधा की पुष्टि होने तक भुगतान उपलब्ध नहीं है।",
    "Close": "बंद करें", "Closing Balance = Opening Balance + Udhari Given − Payment Received + Advance Refunded ± Other Adjustments (if supported). Positive = Outstanding; negative = Advance; zero = Settled.": "अंतिम शेष = शुरुआती शेष + दी गई उधारी − प्राप्त भुगतान + वापस किया गया अग्रिम ± अन्य समायोजन (यदि उपलब्ध हों)। धनात्मक = बकाया; ऋणात्मक = अग्रिम; शून्य = हिसाब बराबर।",
