    "After:": "பிறகு:",
    "All saved changes are synchronized.": "சேமித்த எல்லா மாற்றங்களும் ஒத்திசைக்கப்பட்டன.",
    "Allow WhatsApp / SMS reminders": "WhatsApp / SMS நினைவூட்டல்களை அனுமதிக்கவும்",
    "Another device already resolved these settings. The server version is now saved on this phone.": "மற்றொரு சாதனத்தில் இந்த அமைப்புகளின் முரண்பாடு ஏற்கனவே தீர்க்கப்பட்டது. சேவையகப் பதிப்பு இப்போது இந்தக் கைபேசியில் சேமிக்கப்பட்டுள்ளது.",
    "Another device already resolved this customer change. The server version has been saved on this phone.": "மற்றொரு சாதனத்தில் இந்த வாடிக்கையாளர் மாற்றத்தின் முரண்பாடு ஏற்கனவே தீர்க்கப்பட்டது. சேவையகப் பதிப்பு இந்தக் கைபேசியில் சேமிக்கப்பட்டுள்ளது.",
    "Are you sure you want to logout?": "நிச்சயமாக வெளியேற விரும்புகிறீர்களா?",
