    "Before:": "முன்பு:",
    "Both customer versions remain saved on this phone. Reconnect and try again.": "வாடிக்கையாளரின் இரண்டு பதிப்புகளும் இந்தக் கைபேசியில் சேமிக்கப்பட்டுள்ளன. மீண்டும் இணைத்து முயற்சிக்கவும்.",
    "Both versions remain saved on this phone. Reconnect and try again.": "இரண்டு பதிப்புகளும் இந்தக் கைபேசியில் சேமிக்கப்பட்டுள்ளன. மீண்டும் இணைத்து முயற்சிக்கவும்.",
    "Call Support": "உதவியை அழைக்கவும்",
    "Check the API connection and try again. Your last server data remains unchanged.": "API இணைப்பைச் சரிபார்த்து மீண்டும் முயற்சிக்கவும். சேவையகத்தின் கடைசித் தரவு மாற்றப்படவில்லை.",
    "Check your connection and open Notifications again to retry.": "இணைப்பைச் சரிபார்த்து, மீண்டும் முயற்சிக்க அறிவிப்புகளைத் திறக்கவும்.",
    "Checkout is disabled until Android billing eligibility and a supported native payment integration are confirmed.": "Android பில்லிங் தகுதியும் ஆதரிக்கப்படும் நேட்டிவ் கட்டண இணைப்பும் உறுதிசெய்யப்படும் வரை கட்டண வசதி முடக்கப்பட்டுள்ளது.",
    Close: "மூடவும்",
    "Close language picker": "மொழித் தேர்வியை மூடவும்",
    "Closing Balance = Opening Balance + Udhari Given − Payment Received + Advance Refunded ± Other Adjustments (if supported). Positive = Outstanding; negative = Advance; zero = Settled.": "முடிவு இருப்பு = தொடக்க இருப்பு + வழங்கிய கடன் − பெற்ற பணம் + திருப்பிய முன்பணம் ± பிற சரிசெய்தல்கள் (ஆதரவு இருந்தால்). நேர்மம் = நிலுவை; எதிர்மம் = முன்பணம்; பூஜ்ஜியம் = தீர்ந்தது.",
    "Common Questions": "பொதுவான கேள்விகள்",
