    "Opening Balance = Previous Period’s Closing Balance. For the first recorded period, the original opening position is Opening Outstanding − Opening Advance; those amounts are included in that period’s activity.": "தொடக்க இருப்பு = முந்தைய காலத்தின் முடிவு இருப்பு. முதலில் பதிவு செய்யப்படும் காலத்திற்கு, தொடக்க நிலை என்பது தொடக்க நிலுவை − தொடக்க முன்பணம்; இந்தத் தொகைகள் அந்தக் காலத்தின் செயல்பாட்டில் அடங்கும்.",
    "Open {{channel}}": "{{channel}} திறக்கவும்",
    "Opening balances and credit limit must be between ₹0 and ₹100 crore.": "தொடக்க இருப்புகளும் கடன் வரம்பும் ₹0 முதல் ₹100 கோடிக்குள் இருக்க வேண்டும்.",
    "Opening balances are fixed after creation. Use ledger transactions to record later payments or advance deposits.": "உருவாக்கிய பிறகு தொடக்க இருப்புகளை மாற்ற முடியாது. பின்னர் வரும் கட்டணங்கள் அல்லது முன்பண வைப்புகளைப் பதிவு செய்ய கணக்குப் பரிவர்த்தனைகளைப் பயன்படுத்தவும்.",
    "Opening outstanding is money already owed; opening advance is money already deposited. If both are entered, they are netted into one opening balance.": "தொடக்க நிலுவை என்பது ஏற்கனவே கடனாக உள்ள தொகை; தொடக்க முன்பணம் என்பது ஏற்கனவே செலுத்திய தொகை. இரண்டையும் உள்ளிட்டால் அவை நிகரமாக்கப்பட்டு ஒரே தொடக்க இருப்பாகும்.",
