    "Tax invoice availability depends on the merchant's configured invoicing service.": "কর চালান পাওয়া যাবে কি না তা ব্যবসায়ীর সেট করা চালান পরিষেবার ওপর নির্ভর করে।",
    "The server has a newer customer record. Review the updated conflict before choosing.": "সার্ভারে গ্রাহকের আরও নতুন তথ্য আছে। সিদ্ধান্ত নেওয়ার আগে হালনাগাদ বিরোধটি দেখুন।",
    "The server has a newer value. Review the updated conflict before choosing.": "সার্ভারে আরও নতুন মান আছে। সিদ্ধান্ত নেওয়ার আগে হালনাগাদ বিরোধটি দেখুন।",
    "The server has newer settings. Review the updated conflict before choosing.": "সার্ভারে আরও নতুন সেটিংস আছে। সিদ্ধান্ত নেওয়ার আগে হালনাগাদ বিরোধটি দেখুন।",
    "The server restore succeeded, but the encrypted offline cache could not be refreshed on this device.": "সার্ভার থেকে পুনরুদ্ধার হয়েছে, কিন্তু এই ডিভাইসে এনক্রিপ্ট করা অফলাইন ক্যাশ হালনাগাদ করা যায়নি।",
    "The server’s current plan does not allow this customer to be restored. The customer conflict remains saved on this phone. Upgrade the plan or choose Keep server when connected.": "সার্ভারের বর্তমান প্ল্যানে এই গ্রাহককে পুনরুদ্ধার করা যাবে না। গ্রাহকের বিরোধ এই ফোনে সংরক্ষিত আছে। প্ল্যান আপগ্রেড করুন অথবা সংযোগ থাকলে ‘সার্ভারেরটি রাখুন’ বেছে নিন।",
    "These settings changed on another device while this phone was offline. Both versions are preserved.": "এই ফোন অফলাইনে থাকাকালে অন্য ডিভাইসে সেটিংস বদলেছে। দুই সংস্করণই সংরক্ষিত আছে।",
    "This cannot be undone. Exported backups will not be deleted.": "এই কাজ ফিরিয়ে নেওয়া যাবে না। রপ্তানি করা ব্যাকআপ মুছবে না।",
