    "This permanently removes your shop, customers, transactions, and activity history from the server. Export a backup first.": "এতে সার্ভার থেকে আপনার দোকান, গ্রাহক, লেনদেন ও কার্যকলাপের ইতিহাস স্থায়ীভাবে মুছে যাবে। আগে ব্যাকআপ রপ্তানি করুন।",
