    "The server restore succeeded, but the encrypted offline cache could not be refreshed on this device.": "சேவையக மீட்பு வெற்றியடைந்தது; ஆனால் இந்தச் சாதனத்தின் குறியாக்கப்பட்ட ஆஃப்லைன் தற்காலிகச் சேமிப்பைப் புதுப்பிக்க முடியவில்லை.",
    "The server’s current plan does not allow this customer to be restored. The customer conflict remains saved on this phone. Upgrade the plan or choose Keep server when connected.": "சேவையகத்தின் தற்போதைய திட்டத்தில் இந்த வாடிக்கையாளரை மீட்டெடுக்க முடியாது. வாடிக்கையாளர் முரண்பாடு இந்தக் கைபேசியில் சேமிக்கப்பட்டுள்ளது. திட்டத்தை மேம்படுத்தவும் அல்லது இணைப்பில் இருக்கும்போது ‘சேவையகப் பதிவை வைத்திருக்கவும்’ என்பதைத் தேர்ந்தெடுக்கவும்.",
    "These settings changed on another device while this phone was offline. Both versions are preserved.": "இந்தக் கைபேசி ஆஃப்லைனில் இருந்தபோது மற்றொரு சாதனத்தில் இந்த அமைப்புகள் மாற்றப்பட்டன. இரண்டு பதிப்புகளும் பாதுகாக்கப்பட்டுள்ளன.",
    "This cannot be undone. Exported backups will not be deleted.": "இதை மீட்டெடுக்க முடியாது. ஏற்றுமதி செய்த காப்புப்பிரதிகள் நீக்கப்படாது.",
    "This customer has disabled WhatsApp/SMS reminders.": "இந்த வாடிக்கையாளர் WhatsApp/SMS நினைவூட்டல்களை முடக்கியுள்ளார்.",
    "This file is not a valid Digital Khata backup.": "இந்தக் கோப்பு சரியான Digital Khata காப்புப்பிரதி அல்ல.",
    "This permanently removes your shop, customers, transactions, and activity history from the server. Export a backup first.": "இது உங்கள் கடை, வாடிக்கையாளர்கள், பரிவர்த்தனைகள் மற்றும் செயல்பாட்டு வரலாற்றைச் சேவையகத்திலிருந்து நிரந்தரமாக நீக்கும். முதலில் காப்புப்பிரதியை ஏற்றுமதி செய்யவும்.",
    "Time remaining": "மீதமுள்ள நேரம்",
    "Transaction Conflict Detected": "பரிவர்த்தனை முரண்பாடு கண்டறியப்பட்டது",
    "Transaction changed again": "பரிவர்த்தனை மீண்டும் மாற்றப்பட்டது",
