    "The server has newer settings. Review the updated conflict before choosing.": "సర్వర్‌లో కొత్త సెట్టింగ్‌లు ఉన్నాయి. ఎంచుకునే ముందు తాజా విభేదాన్ని పరిశీలించండి.",
    "The server restore succeeded, but the encrypted offline cache could not be refreshed on this device.": "సర్వర్ పునరుద్ధరణ విజయవంతమైంది, కానీ ఈ పరికరంలోని ఎన్‌క్రిప్ట్ చేసిన ఆఫ్‌లైన్ క్యాష్‌ను నవీకరించలేకపోయాం.",
    "The server’s current plan does not allow this customer to be restored. The customer conflict remains saved on this phone. Upgrade the plan or choose Keep server when connected.": "సర్వర్ ప్రస్తుత ప్లాన్‌లో ఈ కస్టమర్‌ను పునరుద్ధరించలేరు. కస్టమర్ విభేదం ఈ ఫోన్‌లో సేవ్ అయింది. ప్లాన్‌ను అప్‌గ్రేడ్ చేయండి లేదా కనెక్ట్ అయినప్పుడు ‘సర్వర్‌లో ఉన్నదాన్ని ఉంచండి’ ఎంచుకోండి.",
    "These settings changed on another device while this phone was offline. Both versions are preserved.": "ఈ ఫోన్ ఆఫ్‌లైన్‌లో ఉన్నప్పుడు మరో పరికరంలో ఈ సెట్టింగ్‌లు మారాయి. రెండు వెర్షన్‌లూ భద్రంగా ఉన్నాయి.",
    "This cannot be undone. Exported backups will not be deleted.": "ఈ చర్యను వెనక్కి తీసుకోలేరు. ఎగుమతి చేసిన బ్యాకప్‌లు తొలగించబడవు.",
    "This customer has disabled WhatsApp/SMS reminders.": "ఈ కస్టమర్ WhatsApp/SMS రిమైండర్లను ఆపివేశారు.",
