    "This permanently removes your shop, customers, transactions, and activity history from the server. Export a backup first.": "ఇది మీ దుకాణం, కస్టమర్లు, లావాదేవీలు, కార్యకలాపాల చరిత్రను సర్వర్ నుంచి శాశ్వతంగా తొలగిస్తుంది. ముందుగా బ్యాకప్ ఎగుమతి చేయండి.",
