    "Your data remains saved on this phone. Review the sync status and resolve any transaction conflicts.": "আপনার ডেটা এই ফোনে সংরক্ষিত আছে। সিঙ্কের অবস্থা দেখুন এবং লেনদেনের কোনো বিরোধ থাকলে মেটান।",
    "Your khata could not be opened safely": "আপনার খাতা নিরাপদে খোলা যায়নি",
    "Your khata is securely stored with your account and available after you log in again.": "আপনার খাতা অ্যাকাউন্টের সঙ্গে নিরাপদে সংরক্ষিত আছে এবং আবার সাইন ইন করলে পাওয়া যাবে।",
    "Your khata starts here": "আপনার খাতার শুরু এখানে",
    "Your phone and server values are still saved. Reconnect and try again.": "আপনার ফোন ও সার্ভারের মান এখনও সংরক্ষিত আছে। আবার সংযোগ করে চেষ্টা করুন।",
    "Your saved changes remain on this phone and will sync when Wi-Fi or another network is available.": "আপনার সংরক্ষিত পরিবর্তন এই ফোনে থাকবে এবং Wi-Fi বা অন্য নেটওয়ার্ক পাওয়া গেলে সিঙ্ক হবে।",
    "Your saved changes remain on this phone. Check your account and connection before retrying.": "আপনার সংরক্ষিত পরিবর্তন এই ফোনে আছে। আবার চেষ্টা করার আগে অ্যাকাউন্ট ও সংযোগ পরীক্ষা করুন।",
