    Unlimited: "అపరిమితం",
    "Unlimited customers": "అపరిమిత కస్టమర్లు",
    "Use 24-hour HH:MM format. Reset to 10:00.": "24 గంటల HH:MM ఫార్మాట్ ఉపయోగించండి. సమయం 10:00కు రీసెట్ అయింది.",
    "Use a valid date in YYYY-MM-DD format.": "YYYY-MM-DD ఫార్మాట్‌లో సరైన తేదీని ఉపయోగించండి.",
    "Verification code": "ధృవీకరణ కోడ్",
