    "Welcome to": "స్వాగతం",
    "We’ll send a one-time verification code to your mobile number.": "మీ మొబైల్ నంబర్‌కు ఒక్కసారి ఉపయోగించే ధృవీకరణ కోడ్ పంపుతాం.",
    WhatsApp: "WhatsApp",
    "WhatsApp / SMS Share": "WhatsApp / SMS ద్వారా షేర్ చేయండి",
    "WhatsApp Support": "WhatsApp సహాయం",
    "WhatsApp and call support are not configured. Add your business support contact before production release.": "WhatsApp, ఫోన్ సహాయం సెటప్ కాలేదు. యాప్ విడుదలకు ముందు వ్యాపార సహాయ వివరాలను జోడించండి.",
    "You can continue using your khata. Notification registration can be retried later.": "మీ ఖాతాను ఉపయోగించడం కొనసాగించవచ్చు. నోటిఫికేషన్ నమోదు కోసం తర్వాత మళ్లీ ప్రయత్నించవచ్చు.",
    "You can review and send the message in": "సందేశాన్ని పరిశీలించి ఇక్కడ పంపవచ్చు",
    "Your account data syncs with the server. Export backups regularly.": "మీ ఖాతా డేటా సర్వర్‌తో సింక్ అవుతుంది. బ్యాకప్‌లను క్రమం తప్పకుండా ఎగుమతి చేయండి.",
    "Your account is available online, but cached data could not be read on this device.": "మీ ఖాతా ఆన్‌లైన్‌లో ఉంది, కానీ ఈ పరికరంలోని క్యాష్ డేటాను చదవలేకపోయాం.",
    "Your account is available online. Keep an internet connection for changes until offline storage is available.": "మీ ఖాతా ఆన్‌లైన్‌లో ఉంది. ఆఫ్‌లైన్ నిల్వ అందుబాటులోకి వచ్చే వరకు మార్పుల కోసం ఇంటర్నెట్ కనెక్షన్ ఉంచండి.",
    "Your changes remain saved on this phone and will not retry automatically. Open Settings to review the sync status and retry when appropriate.": "మీ మార్పులు ఈ ఫోన్‌లో సేవ్ అయ్యాయి; ఆటోమేటిక్‌గా మళ్లీ ప్రయత్నించబడవు. సింక్ స్థితిని చూసి సరైన సమయంలో మళ్లీ ప్రయత్నించడానికి సెట్టింగ్‌లు తెరవండి.",
    "Your data remains saved on this phone. Review the sync status and resolve any transaction conflicts.": "మీ డేటా ఈ ఫోన్‌లో సేవ్ అయింది. సింక్ స్థితిని చూసి లావాదేవీ విభేదాలు ఉంటే పరిష్కరించండి.",
    "Your khata could not be opened safely": "మీ ఖాతాను సురక్షితంగా తెరవలేకపోయాం",
    "Your khata is securely stored with your account and available after you log in again.": "మీ ఖాతా మీ అకౌంట్‌తో సురక్షితంగా నిల్వ చేయబడింది; మళ్లీ లాగిన్ అయినప్పుడు అందుబాటులో ఉంటుంది.",
    "Your khata starts here": "మీ ఖాతా ఇక్కడ ప్రారంభమవుతుంది",
    "Your phone and server values are still saved. Reconnect and try again.": "మీ ఫోన్, సర్వర్ విలువలు ఇంకా సేవ్ అయ్యాయి. మళ్లీ కనెక్ట్ చేసి ప్రయత్నించండి.",
    "Your saved changes remain on this phone and will sync when Wi-Fi or another network is available.": "మీ సేవ్ చేసిన మార్పులు ఈ ఫోన్‌లో ఉంటాయి; Wi-Fi లేదా మరో నెట్‌వర్క్ అందుబాటులోకి వచ్చినప్పుడు సింక్ అవుతాయి.",
    "Your saved changes remain on this phone. Check your account and connection before retrying.": "మీ సేవ్ చేసిన మార్పులు ఈ ఫోన్‌లో ఉన్నాయి. మళ్లీ ప్రయత్నించే ముందు ఖాతా, కనెక్షన్ తనిఖీ చేయండి.",
    "Your saved changes remain on this phone. Synchronization will retry later.": "మీ సేవ్ చేసిన మార్పులు ఈ ఫోన్‌లో ఉన్నాయి. తర్వాత సింక్ మళ్లీ ప్రయత్నిస్తుంది.",
    "Your saved khata data has not been removed. Restart this screen to try again.": "మీ సేవ్ చేసిన ఖాతా డేటా తొలగించలేదు. మళ్లీ ప్రయత్నించడానికి ఈ స్క్రీన్‌ను తెరవండి.",
    "Your shop is registered, but encrypted offline storage could not be updated on this device.": "మీ దుకాణం నమోదైంది, కానీ ఈ పరికరంలోని ఎన్‌క్రిప్ట్ చేసిన ఆఫ్‌లైన్ నిల్వను అప్‌డేట్ చేయలేకపోయాం.",
    "Your shop is signed in, but encrypted local storage could not be opened. Offline changes are not enabled on this installation.": "మీ దుకాణంలో సైన్ ఇన్ అయింది, కానీ ఎన్‌క్రిప్ట్ చేసిన స్థానిక నిల్వను తెరవలేకపోయాం. ఈ ఇన్‌స్టాలేషన్‌లో ఆఫ్‌లైన్ మార్పులు ప్రారంభం కాలేదు.",
    "Your {{plan}} plan {{remaining}}. Review renewal options in My Subscription.": "మీ {{plan}} ప్లాన్‌కు {{remaining}}. పునరుద్ధరణ ఎంపికలను నా సభ్యత్వంలో చూడండి.",
    "You’re all caught up": "అన్నీ తాజా స్థితిలో ఉన్నాయి",
    "{{count}} customers": "{{count}} మంది కస్టమర్లు",
    "a mobile number already assigned in this shop. The local customer and its ledger remain saved; no records were merged. Change the number on the local customer, then retry synchronization.": "ఈ దుకాణంలో మొబైల్ నంబర్ ఇప్పటికే కేటాయించారు. స్థానిక కస్టమర్, వారి ఖాతా సేవ్ అయ్యాయి; రికార్డులను కలపలేదు. స్థానిక కస్టమర్ నంబర్ మార్చి సింక్ మళ్లీ ప్రయత్నించండి.",
    "customer change": "కస్టమర్ మార్పు",
