    "Your changes remain saved on this phone and will not retry automatically. Open Settings to review the sync status and retry when appropriate.": "ਤੁਹਾਡੀਆਂ ਤਬਦੀਲੀਆਂ ਇਸ ਫ਼ੋਨ 'ਤੇ ਸੰਭਾਲੀਆਂ ਹਨ ਅਤੇ ਆਪਣੇ ਆਪ ਮੁੜ ਨਹੀਂ ਭੇਜੀਆਂ ਜਾਣਗੀਆਂ। ਸਿੰਕ ਦੀ ਸਥਿਤੀ ਵੇਖਣ ਅਤੇ ਠੀਕ ਸਮੇਂ ਮੁੜ ਕੋਸ਼ਿਸ਼ ਲਈ ਸੈਟਿੰਗਾਂ ਖੋਲ੍ਹੋ।",
