    "Your saved changes remain on this phone and will sync when Wi-Fi or another network is available.": "ਤੁਹਾਡੀਆਂ ਸੰਭਾਲੀਆਂ ਤਬਦੀਲੀਆਂ ਇਸ ਫ਼ੋਨ 'ਤੇ ਰਹਿਣਗੀਆਂ ਅਤੇ Wi-Fi ਜਾਂ ਹੋਰ ਨੈੱਟਵਰਕ ਮਿਲਣ 'ਤੇ ਸਿੰਕ ਹੋਣਗੀਆਂ।",
    "Your saved changes remain on this phone. Check your account and connection before retrying.": "ਤੁਹਾਡੀਆਂ ਸੰਭਾਲੀਆਂ ਤਬਦੀਲੀਆਂ ਇਸ ਫ਼ੋਨ 'ਤੇ ਹਨ। ਮੁੜ ਕੋਸ਼ਿਸ਼ ਤੋਂ ਪਹਿਲਾਂ ਖਾਤਾ ਅਤੇ ਜੋੜ ਜਾਂਚੋ।",
    "Your saved changes remain on this phone. Synchronization will retry later.": "ਤੁਹਾਡੀਆਂ ਸੰਭਾਲੀਆਂ ਤਬਦੀਲੀਆਂ ਇਸ ਫ਼ੋਨ 'ਤੇ ਹਨ। ਸਿੰਕ ਬਾਅਦ ਵਿੱਚ ਮੁੜ ਕੋਸ਼ਿਸ਼ ਕਰੇਗਾ।",
    "Your saved khata data has not been removed. Restart this screen to try again.": "ਤੁਹਾਡਾ ਸੰਭਾਲਿਆ ਖਾਤਾ ਡਾਟਾ ਨਹੀਂ ਹਟਾਇਆ ਗਿਆ। ਮੁੜ ਕੋਸ਼ਿਸ਼ ਕਰਨ ਲਈ ਇਹ ਸਕ੍ਰੀਨ ਖੋਲ੍ਹੋ।",
    "Your shop is registered, but encrypted offline storage could not be updated on this device.": "ਤੁਹਾਡੀ ਦੁਕਾਨ ਦਰਜ ਹੈ, ਪਰ ਇਸ ਡਿਵਾਈਸ ਦੀ ਇਨਕ੍ਰਿਪਟ ਕੀਤੀ ਆਫ਼ਲਾਈਨ ਸਟੋਰੇਜ ਅੱਪਡੇਟ ਨਹੀਂ ਹੋ ਸਕੀ।",
    "Your shop is signed in, but encrypted local storage could not be opened. Offline changes are not enabled on this installation.": "ਤੁਹਾਡੀ ਦੁਕਾਨ ਵਿੱਚ ਸਾਈਨ ਇਨ ਹੋ ਗਿਆ ਹੈ, ਪਰ ਇਨਕ੍ਰਿਪਟ ਕੀਤੀ ਸਥਾਨਕ ਸਟੋਰੇਜ ਖੁੱਲ੍ਹ ਨਹੀਂ ਸਕੀ। ਇਸ ਇੰਸਟਾਲੇਸ਼ਨ ਵਿੱਚ ਆਫ਼ਲਾਈਨ ਤਬਦੀਲੀਆਂ ਚਾਲੂ ਨਹੀਂ ਹਨ।",
