    "{{name}}\n\nThis customer was changed on another device while this phone was offline. The phone and server versions are preserved.": "{{name}}\n\nஇந்தக் கைபேசி ஆஃப்லைனில் இருந்தபோது மற்றொரு சாதனத்தில் வாடிக்கையாளர் மாற்றப்பட்டார். கைபேசி மற்றும் சேவையகப் பதிப்புகள் பாதுகாக்கப்பட்டுள்ளன.",
