/** Batch 4 translations are added by reviewed key groups; keep each locale local/offline. */
type Batch4Row = readonly [string, string, string, string, string, string, string, string, string, string];
const batch4Locales = ["mai", "sat", "ks", "kok", "sd", "doi", "mni", "brx", "sa"] as const;
const batch4LocaleColumn = { mai: 1, sat: 2, ks: 3, kok: 4, sd: 5, doi: 6, mni: 7, brx: 8, sa: 9 } as const;
for (const locale of batch4Locales) localeDictionaries[locale] ??= {};
function installBatch4Rows(rows: readonly Batch4Row[]) {
  for (const [key, ...values] of rows) {
    for (const locale of batch4Locales) {
      localeDictionaries[locale][key] = values[batch4LocaleColumn[locale] - 1];
    }
  }
}

